import xml.etree.ElementTree as ET
import xml.etree.ElementTree as ElementTree

class XMLProcessor:
    MAGIC_NUMBER_ERROR = -1

    def __init__(self, file_name):
        self._file_name = file_name
        self._root = None

    @property
    def file_name(self):
        return self._file_name

    @file_name.setter
    def file_name(self, value):
        self._file_name = value

    @property
    def root(self):
        return self._root

    @root.setter
    def root(self, value):
        self._root = value

    def read_xml(self):
        try:
            tree = ET.parse(self.file_name)
            self.root = tree.getroot()
            return self.root
        except Exception:
            return None

    def write_xml(self, file_name):
        try:
            tree = ET.ElementTree(self.root)
            tree.write(file_name)
            return True
        except Exception:
            return False

    def process_xml_data(self, file_name):
        for element in self.root.iter('item'):
            element.text = self.upper_item_text(element.text)
        return self.write_xml(file_name)

    def upper_item_text(self, text):
        if text is None:
            return text
        return text.upper()

    def find_element(self, element_name):
        if self.root is None:
            return []
        return self.root.findall(element_name)

    def update_items_text(self):
        items = self.root.findall('item') if self.root is not None else []
        for item in items:
            item.text = self.upper_item_text(item.text)
